import {BookOpen,Brain,ChartNoAxesColumn,Check,ChevronLeft,ChevronRight,Clock,Download,Flag,GraduationCap,Home,Play,RotateCcw,Search,Settings,SlidersHorizontal,Sparkles,Target,Upload,Wallet,AlertTriangle,CalendarDays,ArrowRight,Bookmark,CheckCircle2,} from 'lucide-react';
import {ResponsiveContainer,AreaChart,Area,Tooltip,XAxis,YAxis,CartesianGrid,BarChart,Bar} from 'recharts';
